from unittest.mock import patch, MagicMock

class Solution:
    def parse_header_links(self, value):
        import re
        links = []
        if not value:
            return links

        # Regex to capture URL, relation, and type from each part
        # It handles optional spaces around delimiters like ; and =
        pattern = re.compile(r'<(?P<url>.*?)>;\s*rel=(?P<rel>[^;]+)(?:;\s*type=\"(?P<type>[^\"]+)\")?')

        parts = [p.strip() for p in value.split(',')]

        for part in parts:
            match = pattern.search(part)
            if match:
                link_data = match.groupdict()
                links.append({
                    'url': link_data['url'],
                    'rel': link_data['rel'].strip(),
                    'type': link_data.get('type')
                })
        return links

def test_parse_header_links():
    solution=Solution()
    value = '<http://example.com/front.jpeg>; rel=front; type="image/jpeg",<http://example.com/back.jpeg>; rel=back;type="image/jpeg"'
    expected = [
        {'url': 'http://example.com/front.jpeg', 'rel': 'front', 'type': 'image/jpeg'},
        {'url': 'http://example.com/back.jpeg', 'rel': 'back', 'type': 'image/jpeg'}
    ]
    assert solution.parse_header_links(value) == expected
