        def check_symmetric(self, array, *, tol=1e-10, raise_warning=True, raise_exception=False):
            if hasattr(array, 'shape') and len(array.shape) != 2:
                raise ValueError("Array must be two-dimensional.")
            rows, cols = array.shape
            if rows != cols:
                raise ValueError("Array must be square.")

            is_symmetric = True
            try:
                for i in range(rows):
                    for j in range(i + 1, cols):
                        if abs(array[i, j] - array[j, i]) > tol:
                            is_symmetric = False
                            break
                    if not is_symmetric:
                        break
            except TypeError: # Handle potential issues with non-numpy/scipy types during indexing if necessary, though we assume valid inputs based on docstring
                 pass


            if not is_symmetric:
                if raise_warning:
                    print("Warning: Array is not symmetric.")
                if raise_exception:
                    raise Exception("Array is not symmetric.")

                if isinstance(array, np.ndarray):
                    return (array + array.T) / 2.0
                elif hasattr(array, 'tocsr'):
                    symmetrized = array + array.transpose()
                    return symmetrized.tocsr()
                else:
                    # Fallback or specific handling for other sparse formats might be needed
                    return None

            return array

    solution = Solution()

    # Test case for a perfectly symmetric NumPy array
    symmetric_array = np.array([[0., 1., 2.], [1., 0., 1.], [2., 1., 0.]])
