def test__pilot_log_lock():
    from pathlib import Path
    from unittest.mock import patch, MagicMock
    import os

    class Solution:
        def _pilot_log_lock(self, lock_dir: Path):
            PILOT_LOG_LOCK_WAIT_SECS = 1.0
            PILOT_LOG_LOCK_STALE_SECS = 60.0

            try:
                os.mkdir(lock_dir)
                return True  # Lock acquired successfully
            except FileExistsError:
                start_time = self._pilot_log_now()
                while self._pilot_log_now() - start_time < PILOT_LOG_LOCK_WAIT_SECS:
                    if lock_dir.exists():
                        mtime = lock_dir.stat().st_mtime
                        current_time = self._pilot_log_now()
                        if current_time - mtime > PILOT_LOG_LOCK_STALE_SECS:
                            try:
                                # Attempt to remove stale lock
                                import shutil
                                shutil.rmtree(lock_dir)
                                continue # Retry acquiring lock after removal
                            except OSError:
                                pass # Couldn't remove, keep waiting/checking
                    else:
                         break # Should not happen if we caught FileExistsError initially, but safety break
                    self._migrate_sleep(0.01)
                return False # Failed to acquire lock within timeout

        def _monotonic_now(self) -> float:
            return 0.0

        def _migrate_sleep(self, seconds: float) -> None:
            pass

        def _pilot_log_now(self) -> float:
            return 0.0


    with patch('os.mkdir') as mock_mkdir, \
         patch.object(Solution, '_pilot_log_now', side_effect=[1.0, 1.01, 1.02]) as mock_pilot_log_now, \
         patch.object(Solution, '_migrate_sleep') as mock_migrate_sleep:

        test_path = Path("/tmp/.lock")

        # Test case where mkdir succeeds immediately (no contention)
        mock_mkdir.side_effect = None
        result = Solution()._pilot_log_lock(test_path)
        assert result is True
        mock_mkdir.assert_called_once_with(test_path)
