                content = f.read()
                lines = content.strip().split('\n')
                if not lines:
                    return []
                headers = [h.strip() for h in lines[0].split(',')]
                data = []
                for i, line in enumerate(lines[1:]):
                    if len(data) >= limit:
                        break
                    values = [v.strip() for v in line.split(',')]
                    if len(values) == len(headers):
